import{_ as o,o as a,c as i,ao as n}from"./chunks/framework.DHldJ08f.js";const f=JSON.parse('{"title":"Notifications","description":"","frontmatter":{"prev":false,"next":false,"title":"Notifications"},"headers":[],"relativePath":"guides/notifications.md","filePath":"guides/notifications.md"}'),r={name:"guides/notifications.md"};function t(s,e,d,l,p,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to “Notifications”">​</a></h1><p>Open Grind supports the following notification categories in Grindr:</p><ul><li><strong>New messages</strong></li><li><strong>Received taps</strong></li></ul><p>To enable notifications, go to <strong>App Settings → Notifications</strong>. Support varies by platform.</p><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to “Android”">​</a></h2><p>On Android, choose one of two modes: <a href="#android-slow-mode">Slow mode</a> (default) or <a href="#android-fast-mode">Fast mode</a> (recommended).</p><p>To change alert level, sound, whether text of the notification appears on the lock screen, change settings in Android system settings directly.</p><h3 id="android-slow-mode" tabindex="-1">Slow mode <a class="header-anchor" href="#android-slow-mode" aria-label="Permalink to “Slow mode”">​</a></h3><p>Slow mode is the default notifications mode on Android. Open Grind checks for new events in the background <strong>about every 15 minutes</strong>. Android may force the interval to be longer, for example in battery saver or when you haven&#39;t opened the app for a while.</p><h3 id="android-fast-mode" tabindex="-1">Fast mode <a class="header-anchor" href="#android-fast-mode" aria-label="Permalink to “Fast mode”">​</a></h3><p>Fast mode on Android <strong>shows notifications instantly</strong>, but uses closed-source Google&#39;s Firebase services, which requires installing Open Grind&#39;s <a href="https://git.opengrind.org/open-grind/fcm-service" target="_blank" rel="noreferrer">FCM service add-on</a> and having Google Play services or microG.</p><p>To enable the fast mode:</p><ol><li>Choose &quot;Fast mode&quot; in Notifications settings</li><li>Tap &quot;Continue&quot; <ul><li>If your version of Open Grind allows direct add-on downloads, it will be downloaded &amp; installed automatically, in which case you can skip the remaining steps</li><li>Otherwise (e.g. when Open Grind was downloaded from F-Droid or Google Play), download and install the add-on manually:</li></ul></li><li>Open <a href="https://git.opengrind.org/open-grind/fcm-service/releases" target="_blank" rel="noreferrer">fcm-service add-on releases</a> page</li><li>Download <code>open-grind-fcm-service-&lt;version&gt;-android.apk</code> and open it; Android asks your browser for permission to install apps once</li><li>Return to Open Grind and choose &quot;Fast mode&quot; again</li></ol><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h2><p>Not supported yet. See <a href="https://git.opengrind.org/open-grind/open-grind/issues/384" target="_blank" rel="noreferrer">#384</a>.</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to “macOS”">​</a></h2><p>Not supported yet. See <a href="https://git.opengrind.org/open-grind/open-grind/issues/385" target="_blank" rel="noreferrer">#385</a>.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h2><p>Not supported yet. See <a href="https://git.opengrind.org/open-grind/open-grind/issues/386" target="_blank" rel="noreferrer">#386</a>.</p>',19)])])}const g=o(r,[["render",t]]);export{f as __pageData,g as default};
